// Nodo "Generar URLs" — arma una búsqueda de catálogo por cada (cadena × marca × término × página).
// Entrada: 1 item con { retailers, marcas, pendientes_ean } desde Supabase.
// Los precios por zona se piden después (nodo "Armar consultas por zona"), sólo para los productos encontrados.
const cfg = $input.first().json;
const retailers = cfg.retailers || [];
const marcas = cfg.marcas || [];

const POR_PAGINA_VTEX = 50;   // máximo que acepta VTEX
const POR_PAGINA_COTO = 60;
// páginas por tipo de marca: las de PepsiCo se recorren más a fondo
const PAGINAS = { pepsico: { vtex: 3, coto: 2 }, competencia: { vtex: 2, coto: 1 }, marca_propia: { vtex: 1, coto: 1 } };

const fecha = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date());
const lista = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);

const out = [];
for (const r of retailers) {
  for (const m of marcas) {
    const solo = lista(m.solo_retailer);
    if (solo.length && !solo.includes(r.id)) continue;
    const pags = PAGINAS[m.tipo] || PAGINAS.pepsico;
    for (const t of String(m.termino || '').split('|').map((x) => x.trim()).filter(Boolean)) {
      const termino = encodeURIComponent(t);
      const meta = { tipo: 'catalogo', retailer_id: r.id, plataforma: r.plataforma, dominio: r.dominio, marca_id: m.id, fecha };
      if (r.plataforma === 'vtex') {
        for (let p = 0; p < pags.vtex; p++) {
          const desde = p * POR_PAGINA_VTEX;
          out.push({ json: { ...meta, pagina: p,
            url: `https://${r.dominio}/api/catalog_system/pub/products/search?ft=${termino}&_from=${desde}&_to=${desde + POR_PAGINA_VTEX - 1}` } });
        }
      } else if (r.plataforma === 'coto') {
        for (let p = 0; p < pags.coto; p++) {
          out.push({ json: { ...meta, pagina: p,
            url: `https://${r.dominio}/sitios/cdigi/categoria?Dy=1&Ntt=${termino}&Nrpp=${POR_PAGINA_COTO}&No=${p * POR_PAGINA_COTO}&format=json` } });
        }
      } else if (r.plataforma === 'laanonima') {
        out.push({ json: { ...meta, pagina: 0, url: `https://${r.dominio}/buscar/${termino}` } });
      }
    }
  }
}

// La Anónima no publica el EAN en el listado: se lee una vez de la ficha de cada producto nuevo.
for (const p of cfg.pendientes_ean || []) {
  if (!p || !p.url || !/^https:\/\//.test(p.url)) continue;
  out.push({ json: { tipo: 'ean', retailer_id: p.retailer_id, sku_retailer: p.sku_retailer, url: p.url, fecha } });
}
return out;

// Nodo "Parsear y filtrar" — convierte las respuestas de cada sitio en filas de precio (zona "web").
// Sólo se quedan productos de las marcas configuradas en la tabla `marcas` (PepsiCo, competencia y marcas propias).

const MARCAS = $('Config').first().json.marcas || [];
const respuestas = $input.all();
const pedidos = $('Generar URLs').all();

// ---------- utilidades ----------
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const normEsp = (s) => ' ' + String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/[´`'’]/g, '').replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const num = (v) => { const n = typeof v === 'number' ? v : parseFloat(String(v ?? '').replace(',', '.')); return Number.isFinite(n) ? n : null; };
const r2 = (n) => (n == null ? null : Math.round(n * 100) / 100);
const lista = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);

// clave normalizada → marcas candidatas (una marca propia sólo vale en su cadena)
const porClave = {};
for (const m of MARCAS) {
  for (const k of [m.id, m.nombre, ...lista(m.alias)].map(norm).filter(Boolean)) (porClave[k] = porClave[k] || []).push(m);
}
const valeEn = (m, retailerId) => { const solo = lista(m.solo_retailer); return !solo.length || solo.includes(retailerId); };
const GENERICAS = /pepsico|pepsi|fritolay|sabritas/;
const ES_SNACK = /snack|papas? fritas?|papas? pay|nacho|tortilla|palito|chizito|mani\b|mani |conito|copetin|picada|aperitivo/;

function detectarMarca(marcaSitio, nombre, retailerId, categorias) {
  const k = norm(marcaSitio);
  let m = (porClave[k] || []).find((x) => valeEn(x, retailerId));
  if (!m && (!k || GENERICAS.test(k))) {         // marca vacía o "PepsiCo": miramos el nombre
    const n = normEsp(nombre);
    m = MARCAS.find((x) => {
      if (x.tipo === 'marca_propia' || !valeEn(x, retailerId)) return false;
      const t = normEsp(x.nombre).trim();
      return t === '3d' ? / 3 ?d /.test(n) : n.includes(' ' + t + ' ');
    });
  }
  if (!m) return null;
  // de las marcas propias sólo interesan los snacks (la marca abarca todo el súper)
  if (m.tipo === 'marca_propia' && !ES_SNACK.test(normEsp(nombre) + ' ' + normEsp(categorias))) return null;
  return m;
}

function gramajeDesdeTexto(txt) {
  const m = String(txt || '').match(/(\d+(?:[.,]\d+)?)\s*(kgs?|kilos?|grs?|gramos|grm|g)\b/i);
  if (!m) return null;
  const v = num(m[1]);
  if (v == null) return null;
  const g = /^k/i.test(m[2]) ? v * 1000 : v;
  return g >= 5 && g <= 5000 ? g : null;
}

// ---------- VTEX (Carrefour, Jumbo, Disco, Vea, Día, ChangoMás) ----------
function parseVtex(productos, meta) {
  const filas = [];
  if (!Array.isArray(productos)) return filas;
  for (const p of productos) {
    const marca = detectarMarca(p.brand, p.productName, meta.retailer_id, (p.categories || []).join(' '));
    if (!marca) continue;
    for (const it of p.items || []) {
      const ean = String(it.ean || '').trim();
      const clave = /^\d{8,14}$/.test(ean) ? ean : `SKU-${meta.retailer_id}-${it.itemId}`;
      const seller = (it.sellers || []).find((s) => s.sellerDefault) || (it.sellers || [])[0] || {};
      const co = seller.commertialOffer || {};
      const precio = num(co.Price) > 0 ? num(co.Price) : null;
      // Los SKUs inactivos de VTEX traen precios basura (ej. $19): sólo tomamos los que están a la venta.
      // Si un producto deja de venderse, la alerta de quiebre lo detecta como "ya no aparece en el sitio".
      if (!co.IsAvailable || precio == null) continue;

      // Precio "antes": algunas cadenas (ej. Cencosud) publican ListPrice en otra escala.
      // Sólo lo tomamos si es mayor al precio y menor a 3 veces el precio.
      let lista = precio;
      for (const cand of [num(co.ListPrice), num(co.PriceWithoutDiscount)]) {
        if (precio && cand && cand > precio && cand < precio * 3) lista = Math.max(lista, cand);
      }
      const teasers = [...(co.Teasers || []), ...(co.PromotionTeasers || []), ...(co.DiscountHighLight || [])]
        .map((t) => t && (t.Name || t.name || t['<Name>k__BackingField']))
        .filter(Boolean);
      const descuento = precio && lista > precio * 1.005;
      const promoTexto = teasers.length
        ? [...new Set(teasers)].join(' | ')
        : descuento ? `-${Math.round((1 - precio / lista) * 100)}% (antes $${Math.round(lista)})` : null;

      const gramaje = gramajeDesdeTexto(it.nameComplete || it.name || p.productName)
        ?? gramajeDesdeTexto((p['Contenido Neto'] || [])[0])
        ?? (/^gr/i.test((p['Gramaje de unidad de medida'] || [])[0] || '') ? num((p['Gramaje de unidad de consumo'] || [])[0]) : null);

      filas.push({
        retailer_id: meta.retailer_id,
        zona_id: 'web',
        ean: clave,
        nombre: it.nameComplete || it.name || p.productName,
        marca: marca.nombre,
        precio: r2(precio),
        precio_lista: r2(lista),
        en_promo: Boolean(descuento || teasers.length),
        promo_texto: promoTexto,
        disponible: Boolean(co.IsAvailable) && (co.AvailableQuantity == null || co.AvailableQuantity > 0) && precio != null,
        url: p.link || (p.linkText ? `https://${meta.dominio}/${p.linkText}/p` : null),
        gramaje_g: gramaje,
        imagen_url: ((it.images || [])[0] || {}).imageUrl || null,
        // datos para pedir el precio por zona (no se guardan)
        sku_id: it.itemId != null ? String(it.itemId) : null,
        seller_id: seller.sellerId != null ? String(seller.sellerId) : '1',
        promo_base: teasers.length ? [...new Set(teasers)].join(' | ') : null,
      });
    }
  }
  return filas;
}

// ---------- Coto Digital (Oracle Endeca, ?format=json) ----------
function buscarRegistros(obj, prof = 0) {
  if (!obj || typeof obj !== 'object' || prof > 12) return null;
  if (obj['@type'] === 'Category_ResultsList' && Array.isArray(obj.records)) return obj.records;
  for (const v of Array.isArray(obj) ? obj : Object.values(obj)) {
    const r = buscarRegistros(v, prof + 1);
    if (r) return r;
  }
  return null;
}
const parseJSONSeguro = (s, def) => { try { return JSON.parse(s); } catch (e) { return def; } };

function parseCoto(data, meta) {
  const filas = [];
  for (const rec of buscarRegistros(data) || []) {
    const r = (rec.records && rec.records[0]) || rec;
    const a = r.attributes || {};
    const g = (k) => (a[k] || [])[0];
    const nombre = g('product.displayName') || g('sku.displayName');
    const marca = detectarMarca(g('product.brand') || g('product.MARCA'), nombre, meta.retailer_id,
      [g('product.category'), g('product.LDEPAR'), g('product.FAMILIA')].filter(Boolean).join(' '));
    if (!marca) continue;

    const ean = String(g('product.eanPrincipal') || '').trim();
    const clave = /^\d{8,14}$/.test(ean) ? ean : `SKU-coto-${g('record.id')}`;
    const precio = num(g('sku.activePrice'));
    const dto = parseJSONSeguro(g('sku.dtoPrice') || '{}', {});
    let lista = precio;
    const pl = num(dto.precioLista);
    if (precio && pl && pl > precio && pl < precio * 3) lista = pl;

    const descuentos = parseJSONSeguro(g('product.dtoDescuentos') || '[]', []);
    const textos = (Array.isArray(descuentos) ? descuentos : [])
      .map((d) => d && (d.textoDescuento || d.descripcion || d.nombre || d.texto))
      .filter(Boolean);
    const descuento = precio && lista > precio * 1.005;

    const q = num(g('sku.quantity'));
    const gramaje = gramajeDesdeTexto(nombre) ?? (q && q >= 5 && q <= 5000 ? q : null);
    const estado = ((r.detailsAction || {}).recordState || '').split('?')[0];

    filas.push({
      retailer_id: meta.retailer_id,
      zona_id: 'web',
      ean: clave,
      nombre,
      marca: marca.nombre,
      precio: r2(precio > 0 ? precio : null),
      precio_lista: r2(lista > 0 ? lista : null),
      en_promo: Boolean(descuento || textos.length),
      promo_texto: textos.length ? [...new Set(textos)].join(' | ')
        : descuento ? `-${Math.round((1 - precio / lista) * 100)}% (antes $${Math.round(lista)})` : null,
      disponible: precio > 0,
      url: estado ? `https://www.cotodigital.com.ar/sitios/cdigi/productos${estado}` : null,
      gramaje_g: gramaje,
      imagen_url: g('product.mediumImage.url') || null,
    });
  }
  return filas;
}

// ---------- La Anónima (HTML: cada producto es un <a data-codigo=… data-precio=…>) ----------
const desEscapar = (s) => String(s || '').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&gt;/g, '>')
  .replace(/&lt;/g, '<').replace(/&amp;/g, '&');

function parseLaAnonima(html, meta) {
  const filas = [];
  const texto = String(html || '');
  for (const m of texto.matchAll(/<a\b[^>]*\bdata-codigo="\d+"[^>]*>/g)) {
    const tag = m[0];
    const attr = (n) => { const x = tag.match(new RegExp('\\s' + n + '="([^"]*)"')); return x ? desEscapar(x[1]).trim() : null; };
    const codigo = attr('data-codigo');
    const nombre = attr('data-nombre');
    if (!codigo || !nombre) continue;
    const marca = detectarMarca(attr('data-marca'), nombre, meta.retailer_id, attr('data-rutacategorias'));
    if (!marca) continue;
    const precio = num(attr('data-precio'));
    const anterior = num(attr('data-precio_anterior'));
    const lista = precio && anterior && anterior > precio && anterior < precio * 3 ? anterior : precio;
    const descuento = precio && lista > precio * 1.005;
    const href = attr('href');
    filas.push({
      retailer_id: meta.retailer_id,
      zona_id: 'web',
      ean: `SKU-${meta.retailer_id}-${codigo}`,     // se reemplaza por el EAN cuando se conoce (tabla equivalencias)
      nombre,
      marca: marca.nombre,
      precio: r2(precio > 0 ? precio : null),
      precio_lista: r2(lista > 0 ? lista : null),
      en_promo: Boolean(descuento),
      promo_texto: descuento ? `-${Math.round((1 - precio / lista) * 100)}% (antes $${Math.round(lista)})` : null,
      disponible: precio > 0,
      url: href ? (href.startsWith('http') ? href : `https://${meta.dominio}${href}`) : null,
      gramaje_g: gramajeDesdeTexto(nombre),
      imagen_url: null,
    });
  }
  return filas;
}

// Ficha de producto de La Anónima → EAN
function eanDeFicha(html) {
  const t = String(html || '');
  const m = t.match(/"gtin\d*"\s*:\s*"(\d{8,14})"/) || t.match(/data-flix-ean="(\d{8,14})"/);
  return m ? m[1] : null;
}

// ---------- recorrer respuestas ----------
const filas = [];
const vistos = new Set();
const errores = [];
const conteo = {};
const equivalencias = [];

for (let i = 0; i < respuestas.length; i++) {
  let meta;
  try { meta = $('Generar URLs').itemMatching(i).json; } catch (e) { meta = (pedidos[i] || {}).json; }
  if (!meta) continue;
  const res = respuestas[i].json || {};
  if (res.error) { errores.push({ url: meta.url, error: String(res.error.message || res.error).slice(0, 200) }); continue; }
  const cuerpo = res.body ?? res.data;

  if (meta.tipo === 'ean') {
    const ean = eanDeFicha(cuerpo);
    if (ean) equivalencias.push({ retailer_id: meta.retailer_id, sku_retailer: meta.sku_retailer, ean });
    continue;
  }

  let nuevas;
  if (meta.plataforma === 'laanonima') {
    if (typeof cuerpo !== 'string' || !/data-codigo=/.test(cuerpo)) {
      // sin productos: o no hay resultados para la búsqueda, o el sitio bloqueó el pedido
      if (typeof cuerpo !== 'string' || /403 ERROR|Request blocked|Access Denied/i.test(cuerpo)) {
        errores.push({ url: meta.url, error: 'La Anónima rechazó el pedido (posible bloqueo por IP del servidor)' });
      }
      continue;
    }
    nuevas = parseLaAnonima(cuerpo, meta);
  } else {
    const data = typeof cuerpo === 'string' ? parseJSONSeguro(cuerpo, null) : cuerpo;
    if (data == null) { errores.push({ url: meta.url, error: 'Respuesta no es JSON (posible bloqueo o página de error)' }); continue; }
    nuevas = meta.plataforma === 'coto' ? parseCoto(data, meta) : parseVtex(data, meta);
  }
  for (const f of nuevas) {
    const k = f.retailer_id + '|' + f.ean;
    if (vistos.has(k)) continue;
    vistos.add(k);
    filas.push(f);
    conteo[f.retailer_id] = (conteo[f.retailer_id] || 0) + 1;
  }
}

const fecha = (pedidos[0] || { json: {} }).json.fecha
  || new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date());

return [{ json: {
  fecha,
  filas,
  equivalencias,
  total: filas.length,
  por_retailer: conteo,
  errores: errores.slice(0, 30),
  cantidad_errores: errores.length,
} }];

// Nodo "Armar consultas por zona" — por cada cadena que regionaliza precios y cada zona activa,
// pide el precio de los productos ya encontrados usando la simulación de carrito de VTEX
// (devuelve precio y disponibilidad para un código postal / sucursal; no crea ningún pedido).
const cfg = $('Config').first().json;
const base = $input.first().json;
const retailers = (cfg.retailers || []).filter((r) => r.plataforma === 'vtex' && ['cp', 'sc'].includes(r.modo_zona));
const zonas = (cfg.zonas || []).filter((z) => z.id !== 'web' && z.cp);
const excepciones = {};
for (const e of cfg.retailer_zonas || []) excepciones[e.retailer_id + '|' + e.zona_id] = e;

const POR_PEDIDO = 40;   // productos por consulta
const out = [];
for (const r of retailers) {
  const prods = (base.filas || []).filter((f) => f.retailer_id === r.id && f.sku_id);
  if (!prods.length) continue;
  for (const z of zonas) {
    const ex = excepciones[r.id + '|' + z.id] || {};
    if (ex.activo === false) continue;
    if (r.modo_zona === 'sc' && !ex.sc) continue;      // cadenas por sucursal: sólo las zonas con sucursal cargada
    const cp = ex.cp || z.cp;
    for (let i = 0; i < prods.length; i += POR_PEDIDO) {
      const lote = prods.slice(i, i + POR_PEDIDO);
      out.push({ json: {
        tipo: 'zona', retailer_id: r.id, zona_id: z.id,
        url: `https://${r.dominio}/api/checkout/pub/orderForms/simulation${ex.sc ? '?sc=' + encodeURIComponent(ex.sc) : ''}`,
        cuerpo: JSON.stringify({
          items: lote.map((f) => ({ id: f.sku_id, quantity: 1, seller: f.seller_id || '1' })),
          country: 'ARG', postalCode: String(cp),
        }),
      } });
    }
  }
}
// Si no hay nada para consultar igual hay que seguir hasta "Guardar": se manda una consulta vacía.
if (!out.length) {
  const r = (cfg.retailers || []).find((x) => x.plataforma === 'vtex') || { dominio: 'www.carrefour.com.ar' };
  out.push({ json: { tipo: 'nada', url: `https://${r.dominio}/api/checkout/pub/orderForms/simulation`,
    cuerpo: JSON.stringify({ items: [], country: 'ARG' }) } });
}
return out;

// Nodo "Unir precios por zona" — suma a las filas "web" una fila por producto, cadena y zona.
const base = $('Parsear y filtrar').first().json;
const pedidos = $('Armar consultas por zona').all();
const respuestas = $input.all();
const r2 = (n) => (n == null ? null : Math.round(n * 100) / 100);
const parseJSONSeguro = (s) => { try { return JSON.parse(s); } catch (e) { return null; } };

const porSku = {};
for (const f of base.filas || []) if (f.sku_id) porSku[f.retailer_id + '|' + f.sku_id] = f;

const grupos = {};          // cadena|zona → filas
const errores = [...(base.errores || [])];
let cantErrores = base.cantidad_errores || 0;

for (let i = 0; i < respuestas.length; i++) {
  let meta;
  try { meta = $('Armar consultas por zona').itemMatching(i).json; } catch (e) { meta = (pedidos[i] || {}).json; }
  if (!meta || meta.tipo !== 'zona') continue;
  const res = respuestas[i].json || {};
  const cuerpo = res.body ?? res.data;
  const data = typeof cuerpo === 'string' ? parseJSONSeguro(cuerpo) : cuerpo;
  if (res.error || !data || !Array.isArray(data.items)) {
    cantErrores++;
    if (errores.length < 30) errores.push({ url: `${meta.url} [${meta.zona_id}]`, error: String((res.error && (res.error.message || res.error)) || 'Respuesta inválida').slice(0, 200) });
    continue;
  }
  const g = (grupos[meta.retailer_id + '|' + meta.zona_id] = grupos[meta.retailer_id + '|' + meta.zona_id] || []);
  for (const it of data.items) {
    const b = porSku[meta.retailer_id + '|' + String(it.id)];
    if (!b) continue;
    const precio = Number(it.sellingPrice ?? it.price) > 0 ? Number(it.sellingPrice ?? it.price) / 100 : null;
    let lista = precio;
    const lp = Number(it.listPrice) / 100;
    if (precio && lp > precio && lp < precio * 3) lista = lp;
    const descuento = precio && lista > precio * 1.005;
    g.push({
      retailer_id: b.retailer_id, zona_id: meta.zona_id, ean: b.ean, nombre: b.nombre, marca: b.marca,
      precio: r2(precio), precio_lista: r2(lista),
      en_promo: Boolean(descuento || b.promo_base),
      promo_texto: b.promo_base || (descuento ? `-${Math.round((1 - precio / lista) * 100)}% (antes $${Math.round(lista)})` : null),
      disponible: it.availability === 'available' && precio != null,
      _entrega: it.availability !== 'cannotBeDelivered',
      url: b.url, gramaje_g: b.gramaje_g, imagen_url: b.imagen_url,
    });
  }
}

const filas = (base.filas || []).map(({ sku_id, seller_id, promo_base, ...f }) => f);
const porZona = {};
const sinCobertura = [];
for (const [k, g] of Object.entries(grupos)) {
  // si la cadena no entrega NINGÚN producto en ese código postal, no opera en la zona: no se guarda nada
  if (!g.some((f) => f._entrega && f.precio != null)) { sinCobertura.push(k); continue; }
  for (const { _entrega, ...f } of g) { if (f.precio != null) filas.push(f); }
  porZona[k] = g.filter((f) => f.precio != null).length;
}

return [{ json: {
  fecha: base.fecha,
  filas,
  equivalencias: base.equivalencias || [],
  total: filas.length,
  por_retailer: base.por_retailer,
  por_zona: porZona,
  sin_cobertura: sinCobertura,
  errores: errores.slice(0, 30),
  cantidad_errores: cantErrores,
} }];
